import graphics from "./library-graphics.json";

// Schematic navigation art, not diagnostic images and not positioning scenes. The drawings are data generated by
// scripts/library-graphics (traced-outline and project-geometry derived, or hand-built); one viewBox, one stroke width,
// no text, never mirrored with the locale.
type Role = "fill" | "bone" | "line";
const ART = graphics.graphics as Record<string, readonly { role: Role; d: string }[]>;
export const STROKE_WIDTH = 3.5;

export function ExamGraphic({ kind }: { kind: string }) {
  const parts = ART[kind] ?? ART.generic!;
  return <svg className="exam-graphic" data-graphic={kind} viewBox={`0 0 ${graphics.viewBox[0]} ${graphics.viewBox[1]}`} aria-hidden="true" focusable="false">
    <g fill="none" stroke="currentColor" strokeWidth={STROKE_WIDTH} strokeLinecap="round" strokeLinejoin="round">
      {parts.map((part, i) => part.role === "fill" ? <path key={i} d={part.d} fill="var(--art-soft)" stroke="none" /> : <path key={i} d={part.d} />)}
    </g>
  </svg>;
}
